style.css:
@-moz-document domain("roblox.com") {
/* Custom Wallpaper */
    body {
        background-image: url("https://wallpaper.dog/large/20504182.jpg");
        background-size: cover;
        background-attachment: fixed;
    }

    /* Optional: Makes the main page elements slightly transparent */
    #container, .content {
        background: rgba(0, 0, 0, 0.7) !important;
        border-radius: 10px;
    }

    /* Change Play Button to Yellow */
    .play-button {
        background-color: #FFD700 !important; /* Gold/Yellow */
        color: black !important; /* Text color */
        border-radius: 8px !important;
        font-weight: bold !important;
        transition: 0.3s ease-in-out;
    }

    /* Hover Effect for Play Button */
    .play-button:hover {
        background-color: #FFC000 !important; /* Darker Yellow */
        transform: scale(1.05);
    }
}
